css:
li{display:flex;justify-content:space-between;align-items:center;padding:14px 0;border-bottom:1px solid #ececef}
li:last-child{border-bottom:0}
.go{width:16px;height:16px;border:1px solid currentColor;border-radius:50%;display:grid;place-content:center;font-size:9px}
/* 写真に重ねる版 */
.more{position:absolute;right:16px;bottom:16px;width:28px;height:28px;border:1px solid rgba(255,255,255,.9);border-radius:50%;display:grid;place-content:center}
.more::after{content:"";width:10px;height:1px;background:#fff;transform:rotate(-45deg)}
/* 文字幅ぶんだけの下線 */
a.txt{text-decoration:underline;text-decoration-thickness:1px;text-underline-offset:5px}
/* 箱を持たない送り矢印 */
.nav{width:20px;height:20px;padding:0;background:none;border:0;border-left:1px solid #fff;border-bottom:1px solid #fff;border-radius:0;transform:rotate(45deg)}
.nav.next{transform:rotate(-135deg)}
/* 版面の外へ出す */
.pager{position:absolute;bottom:-46px;left:0;right:0;display:flex;justify-content:space-between}
